fn reverse_digits(n: Int) -> Option<Int> {
    if n <= 0 {
        return None;
    }
    let mut result = 0;
    while n > 0 {
        let digit = n % 10;
        result = result * 10 + digit;
        n /= 10;
    }
    Some(result)
}

